CREATE TABLE IF NOT EXISTS brands (id text PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true, position integer NOT NULL DEFAULT 0, version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS categories (id text PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, active boolean NOT NULL DEFAULT true, position integer NOT NULL DEFAULT 0, version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS subcategories (id text PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, category_id text NOT NULL REFERENCES categories(id), active boolean NOT NULL DEFAULT true, position integer NOT NULL DEFAULT 0, version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS sizes (id text PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, type text NOT NULL CHECK(type IN ('volume','mass','count','text')), value numeric, unit text, active boolean NOT NULL DEFAULT true, position integer NOT NULL DEFAULT 0, version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS brand_categories (brand_id text REFERENCES brands(id) ON DELETE CASCADE, category_id text REFERENCES categories(id), PRIMARY KEY(brand_id,category_id));
CREATE TABLE IF NOT EXISTS brand_subcategories (brand_id text REFERENCES brands(id) ON DELETE CASCADE, subcategory_id text REFERENCES subcategories(id), PRIMARY KEY(brand_id,subcategory_id));
CREATE TABLE IF NOT EXISTS brand_sizes (brand_id text REFERENCES brands(id) ON DELETE CASCADE, size_id text REFERENCES sizes(id), PRIMARY KEY(brand_id,size_id));
CREATE TABLE IF NOT EXISTS products (id text PRIMARY KEY, sku text NOT NULL UNIQUE, name text NOT NULL, brand_id text NOT NULL REFERENCES brands(id), category_id text NOT NULL REFERENCES categories(id), subcategory_id text REFERENCES subcategories(id), size_id text NOT NULL REFERENCES sizes(id), wholesale_price numeric(14,2) NOT NULL CHECK(wholesale_price >= 0), retail_price numeric(14,2) CHECK(retail_price >= 0), stock integer NOT NULL DEFAULT 0 CHECK(stock >= 0), active boolean NOT NULL DEFAULT false, position integer NOT NULL DEFAULT 0, data jsonb NOT NULL DEFAULT '{}', version integer NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS products_filters ON products(brand_id,category_id,size_id,active);
CREATE INDEX IF NOT EXISTS products_name ON products(lower(name));
CREATE TABLE IF NOT EXISTS pages (id text PRIMARY KEY, data jsonb NOT NULL, version integer NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS page_products (page_id text REFERENCES pages(id) ON DELETE CASCADE, product_id text REFERENCES products(id) ON DELETE CASCADE, position integer NOT NULL, PRIMARY KEY(page_id,product_id));
CREATE TABLE IF NOT EXISTS settings (key text PRIMARY KEY, value jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS roles (id text PRIMARY KEY, name text UNIQUE NOT NULL, description text NOT NULL DEFAULT '', system boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS permissions (id text PRIMARY KEY, key text NOT NULL UNIQUE, capability text NOT NULL, name text NOT NULL, system boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS role_permissions (role_id text REFERENCES roles(id) ON DELETE CASCADE, permission_id text REFERENCES permissions(id) ON DELETE CASCADE, PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS user_roles (user_id text NOT NULL, role_id text REFERENCES roles(id) ON DELETE CASCADE, brand_ids text[], PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS audit_log (id bigserial PRIMARY KEY, user_id text, action text NOT NULL, entity_id text, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS import_jobs (id uuid PRIMARY KEY, user_id text NOT NULL, kind text NOT NULL CHECK(kind IN ('products','media')), status text NOT NULL DEFAULT 'preview', filename text NOT NULL, mode text NOT NULL DEFAULT 'upsert', total integer NOT NULL DEFAULT 0, done integer NOT NULL DEFAULT 0, errors integer NOT NULL DEFAULT 0, data jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS import_rows (job_id uuid REFERENCES import_jobs(id) ON DELETE CASCADE, row_number integer NOT NULL, status text NOT NULL, sku text, data jsonb NOT NULL DEFAULT '{}', errors jsonb NOT NULL DEFAULT '[]', PRIMARY KEY(job_id,row_number));
CREATE INDEX IF NOT EXISTS import_job_owner ON import_jobs(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS media_assets (id uuid PRIMARY KEY, job_id uuid REFERENCES import_jobs(id), sku text, original_name text NOT NULL, object_key text NOT NULL, thumbnail_key text NOT NULL, checksum text NOT NULL, bytes integer NOT NULL, width integer NOT NULL, height integer NOT NULL, product_id text REFERENCES products(id) ON DELETE SET NULL, created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits (key text PRIMARY KEY, count integer NOT NULL, expires_at timestamptz NOT NULL);
ALTER TABLE media_assets ADD COLUMN IF NOT EXISTS position integer NOT NULL DEFAULT 0;
